<script setup>
import { computed, onMounted, ref } from "vue";
import { api, normalizeList } from "../../services/api";
import AppIcon from "../../components/ui/AppIcon.vue";
const bills = ref([]); const payments = ref([]); const loading = ref(true); const error = ref(""); const busy = ref("");
const selectedBill = ref(null); const paymentForm = ref({ amount: "", paymentDate: new Date().toISOString().slice(0,10), reference: "", method: "bank_transfer", evidence: "" });
const totals = computed(() => ({ due: bills.value.filter(x => ["unpaid", "partially_paid", "overdue"].includes(x.paymentStatus)).length, verify: payments.value.filter(x => x.status === "awaiting_verification").length, reconcile: payments.value.filter(x => x.status === "verified").length }));
const money = (amount, currency="NGN") => new Intl.NumberFormat("en-NG", { style:"currency", currency, maximumFractionDigits:2 }).format(Number(amount || 0));
async function load() { loading.value = true; error.value = ""; try { const [b,p] = await Promise.all([api.listBills(), api.listPayments()]); bills.value = normalizeList(b, ["bills"]); payments.value = normalizeList(p, ["payments"]); } catch(e) { error.value = e.message || "Unable to load finance records."; } finally { loading.value = false; } }
async function action(payment, type) { busy.value = payment._id; try { await api.updatePaymentAction(payment._id, type); await load(); } catch(e) { error.value = e.message || "Payment action failed."; } finally { busy.value = ""; } }
function beginPayment(bill) { selectedBill.value = bill; paymentForm.value = { amount: "", paymentDate: new Date().toISOString().slice(0,10), reference: "", method: "bank_transfer", evidence: "" }; }
async function savePayment() { if (!selectedBill.value) return; busy.value = "record"; error.value = ""; try { await api.recordPayment({ ...paymentForm.value, billId: selectedBill.value._id }); selectedBill.value = null; await load(); } catch(e) { error.value = e.message || "Unable to record payment."; } finally { busy.value = ""; } }
onMounted(load);
</script>
<template>
  <section class="finance-page">
    <header class="finance-heading"><div><span class="eyebrow">FINANCE WORKSPACE</span><h1>Bills & Payments</h1><p>Track approved bills, record actual payments and complete verification separately.</p></div><button class="refresh-btn" @click="load"><AppIcon name="refresh" :size="16"/> Refresh</button></header>
    <div class="finance-stats"><article><span>Outstanding bills</span><strong>{{ totals.due }}</strong></article><article><span>Awaiting verification</span><strong>{{ totals.verify }}</strong></article><article><span>Awaiting reconciliation</span><strong>{{ totals.reconcile }}</strong></article></div>
    <p v-if="error" class="finance-error">{{ error }}</p><div v-if="loading" class="finance-empty">Loading finance records…</div>
    <template v-else>
      <section class="finance-panel"><div class="panel-title"><div><h2>Bills Register</h2><p>Approval does not mean a bill has been paid.</p></div><span>{{ bills.length }} records</span></div>
        <div v-if="!bills.length" class="finance-empty">No bill records yet. Payment-required Approval Memos will appear here after submission.</div>
        <div v-else class="finance-table-wrap"><table><thead><tr><th>Bill / Service</th><th>Vendor</th><th>Amount</th><th>Due date</th><th>Approval</th><th>Payment</th></tr></thead><tbody><tr v-for="bill in bills" :key="bill._id"><td><b>{{ bill.reference }}</b><small>{{ bill.category }} · {{ bill.description }}</small></td><td>{{ bill.vendor }}</td><td>{{ money(bill.amount,bill.currency) }}</td><td>{{ bill.dueDate ? new Date(bill.dueDate).toLocaleDateString() : "—" }}</td><td><span class="status-pill">{{ bill.approvalStatus }}</span></td><td><span class="status-pill" :class="bill.paymentStatus">{{ bill.paymentStatus }}</span><button v-if="bill.approvalStatus==='approved' && !['verified','reconciled','closed'].includes(bill.paymentStatus)" class="record-btn" @click="beginPayment(bill)">Record payment</button></td></tr></tbody></table></div>
      </section>
      <section v-if="selectedBill" class="finance-panel payment-form-panel"><div class="panel-title"><div><h2>Record payment</h2><p>{{ selectedBill.reference }} · {{ selectedBill.vendor }} · {{ money(selectedBill.amount, selectedBill.currency) }}</p></div><button class="refresh-btn" @click="selectedBill=null">Cancel</button></div><form class="payment-form" @submit.prevent="savePayment"><label>Payment amount<input v-model="paymentForm.amount" type="number" min="0.01" step="0.01" required /></label><label>Payment date<input v-model="paymentForm.paymentDate" type="date" required /></label><label>Payment reference<input v-model="paymentForm.reference" required placeholder="Bank / transaction reference" /></label><label>Method<select v-model="paymentForm.method"><option value="bank_transfer">Bank transfer</option><option value="cheque">Cheque</option><option value="cash">Cash</option><option value="card">Card</option><option value="other">Other</option></select></label><label class="wide">Evidence file reference / URL<input v-model="paymentForm.evidence" placeholder="Evidence attachment reference" /></label><div class="wide form-actions"><small>Recording a payment does not verify it. Finance verification and reconciliation are separate actions.</small><button class="submit-payment" type="submit" :disabled="busy==='record'">{{ busy==='record' ? 'Saving…' : 'Record payment' }}</button></div></form></section>
      <section class="finance-panel"><div class="panel-title"><div><h2>Payment Activity</h2><p>Evidence upload does not automatically verify a payment.</p></div><span>{{ payments.length }} records</span></div>
        <div v-if="!payments.length" class="finance-empty">No payments recorded yet. Finance can record a payment against an approved bill through the payment API.</div>
        <div v-else class="finance-table-wrap"><table><thead><tr><th>Payment reference</th><th>Bill</th><th>Amount</th><th>Date</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="payment in payments" :key="payment._id"><td><b>{{ payment.reference }}</b><small>{{ payment.method }}</small></td><td>{{ payment.bill?.reference || "Bill" }}</td><td>{{ money(payment.amount,payment.currency) }}</td><td>{{ new Date(payment.paymentDate).toLocaleDateString() }}</td><td><span class="status-pill" :class="payment.status">{{ payment.status }}</span></td><td class="action-cell"><button v-if="payment.status==='awaiting_verification'" :disabled="busy===payment._id" @click="action(payment,'verify')">Verify</button><button v-if="payment.status==='verified'" :disabled="busy===payment._id" @click="action(payment,'reconcile')">Reconcile</button></td></tr></tbody></table></div>
      </section>
    </template>
  </section>
</template>
<style scoped>
.finance-page{max-width:1440px;margin:0 auto;padding:28px;display:grid;gap:20px;color:var(--text-primary,#172033)}.finance-heading{display:flex;justify-content:space-between;align-items:center;gap:16px}.eyebrow{font-size:11px;font-weight:800;letter-spacing:.13em;color:var(--primary,#2563eb)}h1{font-size:28px;margin:6px 0}p{color:var(--text-secondary,#64748b);margin:5px 0}.refresh-btn,.action-cell button{display:inline-flex;align-items:center;gap:7px;border:1px solid var(--border,#dbe2ea);background:var(--surface,#fff);border-radius:10px;padding:10px 14px;font-weight:700;cursor:pointer}.finance-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.finance-stats article,.finance-panel{background:var(--surface,#fff);border:1px solid var(--border,#e2e8f0);border-radius:16px;padding:18px;box-shadow:0 5px 20px #0f172a08}.finance-stats span{display:block;color:var(--text-secondary,#64748b);font-size:13px}.finance-stats strong{display:block;font-size:27px;margin-top:8px}.panel-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.panel-title h2{font-size:17px;margin:0}.panel-title>span{font-size:12px;color:var(--text-secondary,#64748b)}.finance-table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:720px}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--border,#e2e8f0);font-size:13px}th{color:var(--text-secondary,#64748b);font-size:11px;text-transform:uppercase;letter-spacing:.06em}td small{display:block;color:var(--text-secondary,#64748b);margin-top:4px}.status-pill{display:inline-flex;border-radius:99px;background:#eef2ff;color:#4338ca;padding:5px 9px;font-size:11px;font-weight:700}.status-pill.verified,.status-pill.reconciled{background:#dcfce7;color:#166534}.status-pill.rejected,.status-pill.overdue{background:#fee2e2;color:#991b1b}.status-pill.partially_paid,.status-pill.awaiting_verification{background:#fef3c7;color:#92400e}.action-cell button{padding:7px 10px;font-size:11px}.record-btn{display:block;margin-top:7px;border:0;background:#dbeafe;color:#1d4ed8;border-radius:7px;padding:6px 9px;font-size:11px;font-weight:700;cursor:pointer}.payment-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.payment-form label{display:grid;gap:6px;font-size:12px;font-weight:700}.payment-form input,.payment-form select{width:100%;min-width:0;padding:10px;border:1px solid var(--border,#dbe2ea);border-radius:9px;background:var(--surface,#fff);color:inherit}.payment-form .wide{grid-column:1/-1}.form-actions{display:flex;justify-content:space-between;align-items:center;gap:12px}.form-actions small{color:var(--text-secondary,#64748b)}.submit-payment{border:0;background:var(--primary,#2563eb);color:#fff;border-radius:9px;padding:10px 15px;font-weight:700;cursor:pointer}.finance-empty{padding:24px;text-align:center;color:var(--text-secondary,#64748b);background:var(--surface-muted,#f8fafc);border-radius:12px;font-size:13px}.finance-error{color:#b91c1c;background:#fef2f2;padding:12px;border-radius:10px}@media(max-width:700px){.finance-page{padding:16px}.finance-heading{align-items:flex-start;flex-direction:column}.finance-stats{grid-template-columns:1fr}.finance-stats article{padding:14px}.payment-form{grid-template-columns:1fr}.payment-form .wide{grid-column:auto}.form-actions{align-items:flex-start;flex-direction:column}}
</style>
